cat <<'EOF' > src/format.rs
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ByteFormat {
    Binary,
    Metric,
    Bytes,
    Gb,
    Gib,
    Mb,
    Mib,
}

impl ByteFormat {
    pub fn parse(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "binary" => Some(Self::Binary),
            "metric" => Some(Self::Metric),
            "bytes" => Some(Self::Bytes),
            "gb" => Some(Self::Gb),
            "gib" => Some(Self::Gib),
            "mb" => Some(Self::Mb),
            "mib" => Some(Self::Mib),
            _ => None,
        }
    }

    pub fn display(&self, bytes: u64) -> String {
        match self {
            Self::Binary => {
                let b = bytes as f64;
                if bytes <= 1024 {
                    format!("{:>7}   B", bytes)
                } else if bytes <= 1024 * 1024 {
                    format!("{:>7.2} KiB", b / 1024.0)
                } else if bytes <= 1024 * 1024 * 1024 {
                    format!("{:>7.2} MiB", b / (1024.0 * 1024.0))
                } else if bytes <= 1024 * 1024 * 1024 * 1024 {
                    format!("{:>7.2} GiB", b / (1024.0 * 1024.0 * 1024.0))
                } else if bytes <= 1024 * 1024 * 1024 * 1024 * 1024 {
                    format!("{:>7.2} TiB", b / (1024.0 * 1024.0 * 1024.0 * 1024.0))
                } else if bytes <= 1024 * 1024 * 1024 * 1024 * 1024 * 1024 {
                    format!("{:>7.2} PiB", b / (1024.0 * 1024.0 * 1024.0 * 1024.0 * 1024.0))
                } else {
                    format!("{:>7.2} EiB", b / (1024.0 * 1024.0 * 1024.0 * 1024.0 * 1024.0 * 1024.0))
                }
            }
            Self::Metric => {
                let b = bytes as f64;
                if bytes <= 1000 {
                    format!("{:>7}  B", bytes)
                } else if bytes <= 1000 * 1000 {
                    format!("{:>7.2} KB", b / 1000.0)
                } else if bytes <= 1000 * 1000 * 1000 {
                    format!("{:>7.2} MB", b / (1000.0 * 1000.0))
                } else if bytes <= 1000 * 1000 * 1000 * 1000 {
                    format!("{:>7.2} GB", b / (1000.0 * 1000.0 * 1000.0))
                } else if bytes <= 1000 * 1000 * 1000 * 1000 * 1000 {
                    format!("{:>7.2} TB", b / (1000.0 * 1000.0 * 1000.0 * 1000.0))
                } else if bytes <= 1000 * 1000 * 1000 * 1000 * 1000 * 1000 {
                    format!("{:>7.2} PB", b / (1000.0 * 1000.0 * 1000.0 * 1000.0 * 1000.0))
                } else {
                    format!("{:>7.2} EB", b / (1000.0 * 1000.0 * 1000.0 * 1000.0 * 1000.0 * 1000.0))
                }
            }
            Self::Bytes => format!("{:>10} b", bytes),
            Self::Gb => format!("{:>7.2} GB", bytes as f64 / 1e9),
            Self::Gib => format!("{:>6.2} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0)),
            Self::Mb => format!("{:>9.2} MB", bytes as f64 / 1e6),
            Self::Mib => format!("{:>8.2} MiB", bytes as f64 / (1024.0 * 1024.0)),
        }
    }
}
EOF"}

