{"command":"cat <<'EOF' > src/logging.rs
use std::fs::OpenOptions;
use std::io::Write;
use std::path::Path;
use std::sync::Mutex;
use std::time::SystemTime;

pub struct Logger {
    file: Option<Mutex<std::fs::File>>,
}

static LOGGER: Logger = Logger { file: None };

pub fn init_log(path: &Path) {
    if let Ok(file) = OpenOptions::new().create(true).append(true).open(path) {
        unsafe {
            // Simple process-level logger initialization
            let logger = &LOGGER as *const Logger as *mut Logger;
            (*logger).file = Some(Mutex::new(file));
        }
    }
}

pub fn log_info(msg: &str) {
    if let Some(ref lock) = LOGGER.file {
        if let Ok(mut f) = lock.lock() {
            let now = SystemTime::now();
            let datetime: chrono::DateTime<chrono::Local> = now.into();
            let time_str = datetime.format("%H:%M:%S").to_string();
            let _ = writeln!(f, "{} [INFO] {}", time_str, msg);
        }
    }
}
EOF"}

