{"command":"cat <<'EOF' > src/args.rs
use clap::{Arg, ArgAction, Command};
use std::path::PathBuf;
use crate::format::ByteFormat;

#[derive(Debug, Clone)]
pub enum SubCommand {
    Aggregate {
        stats: bool,
        no_sort: bool,
        no_total: bool,
        inputs: Vec<PathBuf>,
    },
    Interactive {
        no_entry_check: bool,
        inputs: Vec<PathBuf>,
    },
    Completions {
        shell: String,
    },
}

#[derive(Debug, Clone)]
pub struct CliArgs {
    pub threads: usize,
    pub format: ByteFormat,
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_filesystem: bool,
    pub ignore_dirs: Vec<PathBuf>,
    pub log_file: Option<PathBuf>,
    pub subcommand: SubCommand,
}

pub fn build_cli() -> Command {
    Command::new("dua")
        .version("2.32.2")
        .about("A tool to learn about disk usage, fast!")
        .arg(
            Arg::new("threads")
                .short('t')
                .long("threads")
                .value_name("THREADS")
                .default_value("0")
                .help("The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread")
        )
        .arg(
            Arg::new("format")
                .short('f')
                .long("format")
                .value_name("FORMAT")
                .default_value("binary")
                .value_parser(["metric", "binary", "bytes", "gb", "gib", "mb", "mib"])
                .help("The format with which to print byte counts")
        )
        .arg(
            Arg::new("apparent-size")
                .short('A')
                .long("apparent-size")
                .action(ArgAction::SetTrue)
                .help("Display apparent size instead of disk usage")
        )
        .arg(
            Arg::new("count-hard-links")
                .short('l')
                .long("count-hard-links")
                .action(ArgAction::SetTrue)
                .help("Count hard-linked files each time they are seen")
        )
        .arg(
            Arg::new("stay-on-filesystem")
                .short('x')
                .long("stay-on-filesystem")
                .action(ArgAction::SetTrue)
                .help("If set, we will not cross filesystems or traverse mount points")
        )
        .arg(
            Arg::new("ignore-dirs")
                .short('i')
                .long("ignore-dirs")
                .value_name("IGNORE_DIRS")
                .action(ArgAction::Append)
                .default_values(["/proc", "/dev", "/sys", "/run"])
                .help("One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path.\n\nHence, they will only be ignored if they are eventually reached as part of the traversal.")
        )
        .arg(
            Arg::new("log-file")
                .long("log-file")
                .value_name("LOG_FILE")
                .help("Write a log file with debug information, including panics")
        )
        .arg(
            Arg::new("input")
                .value_name("INPUT")
                .action(ArgAction::Append)
                .help("One or more input files or directories. If unset, we will use all entries in the current working directory")
        )
        .subcommand(
            Command::new("interactive")
                .alias("i")
                .about("Launch the terminal user interface")
                .arg(
                    Arg::new("no-entry-check")
                        .short('e')
                        .long("no-entry-check")
                        .action(ArgAction::SetTrue)
                        .help("Do not check entries for presence when listing a directory to avoid slugging performance on slow filesystems")
                )
                .arg(
                    Arg::new("input")
                        .value_name("INPUT")
                        .action(ArgAction::Append)
                        .help("One or more input files or directories. If unset, we will use all entries in the current working directory")
                )
        )
        .subcommand(
            Command::new("aggregate")
                .alias("a")
                .about("Aggregate the consumed space of one or more directories or files")
                .arg(
                    Arg::new("stats")
                        .long("stats")
                        .action(ArgAction::SetTrue)
                        .help("If set, print additional statistics about the file traversal to stderr")
                )
                .arg(
                    Arg::new("no-sort")
                        .long("no-sort")
                        .action(ArgAction::SetTrue)
                        .help("If set, paths will be printed in their order of occurrence on the command-line. Otherwise they are sorted by their size in bytes, ascending")
                )
                .arg(
                    Arg::new("no-total")
                        .long("no-total")
                        .action(ArgAction::SetTrue)
                        .help("If set, no total column will be computed for multiple inputs")
                )
                .arg(
                    Arg::new("input")
                        .value_name("INPUT")
                        .action(ArgAction::Append)
                        .help("One or more input files or directories. If unset, we will use all entries in the current working directory")
                )
        )
        .subcommand(
            Command::new("completions")
                .about("Generate shell completions")
                .arg(
                    Arg::new("shell")
                        .value_name("SHELL")
                        .required(true)
                        .value_parser(["bash", "elvish", "fish", "powershell", "zsh"])
                        .help("The shell to generate a completions-script for")
                )
        )
}

pub fn parse_cli() -> CliArgs {
    let matches = build_cli().get_matches();

    let threads: usize = matches
        .get_one::<String>("threads")
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);

    let format_str = matches
        .get_one::<String>("format")
        .map(|s| s.as_str())
        .unwrap_or("binary");
    let format = ByteFormat::parse(format_str).unwrap_or(ByteFormat::Binary);

    let apparent_size = matches.get_flag("apparent-size");
    let count_hard_links = matches.get_flag("count-hard-links");
    let stay_on_filesystem = matches.get_flag("stay-on-filesystem");

    let ignore_dirs: Vec<PathBuf> = matches
        .get_many::<String>("ignore-dirs")
        .unwrap_or_default()
        .map(|s| PathBuf::from(s))
        .collect();

    let log_file = matches.get_one::<String>("log-file").map(PathBuf::from);

    let subcommand = match matches.subcommand() {
        Some(("interactive", sub_m)) => {
            let no_entry_check = sub_m.get_flag("no-entry-check");
            let inputs: Vec<PathBuf> = sub_m
                .get_many::<String>("input")
                .unwrap_or_default()
                .map(PathBuf::from)
                .collect();
            SubCommand::Interactive {
                no_entry_check,
                inputs,
            }
        }
        Some(("aggregate", sub_m)) => {
            let stats = sub_m.get_flag("stats");
            let no_sort = sub_m.get_flag("no-sort");
            let no_total = sub_m.get_flag("no-total");
            let inputs: Vec<PathBuf> = sub_m
                .get_many::<String>("input")
                .unwrap_or_default()
                .map(PathBuf::from)
                .collect();
            SubCommand::Aggregate {
                stats,
                no_sort,
                no_total,
                inputs,
            }
        }
        Some(("completions", sub_m)) => {
            let shell = sub_m.get_one::<String>("shell").cloned().unwrap_or_default();
            SubCommand::Completions { shell }
        }
        _ => {
            let inputs: Vec<PathBuf> = matches
                .get_many::<String>("input")
                .unwrap_or_default()
                .map(PathBuf::from)
                .collect();
            SubCommand::Aggregate {
                stats: false,
                no_sort: false,
                no_total: false,
                inputs,
            }
        }
    };

    CliArgs {
        threads,
        format,
        apparent_size,
        count_hard_links,
        stay_on_filesystem,
        ignore_dirs,
        log_file,
        subcommand,
    }
}
EOF"}

