use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use rayon::prelude::*;

#[derive(Clone, Debug)]
pub struct TraversalOptions {
    pub threads: usize,
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_filesystem: bool,
    pub ignore_dirs: Vec<PathBuf>,
}

#[derive(Debug, Clone, Default)]
pub struct TraversalStats {
    pub entries_traversed: usize,
    pub smallest_file_bytes: u64,
    pub largest_file_bytes: u64,
    pub num_errors: usize,
}

impl TraversalStats {
    pub fn merge(&mut self, other: &TraversalStats) {
        self.entries_traversed += other.entries_traversed;
        self.num_errors += other.num_errors;
        if other.entries_traversed > 0 {
            if self.entries_traversed == other.entries_traversed {
                self.smallest_file_bytes = other.smallest_file_bytes;
                self.largest_file_bytes = other.largest_file_bytes;
            } else {
                self.smallest_file_bytes = self.smallest_file_bytes.min(other.smallest_file_bytes);
                self.largest_file_bytes = self.largest_file_bytes.max(other.largest_file_bytes);
            }
        }
    }

    pub fn record_file(&mut self, size: u64) {
        if self.entries_traversed == 0 {
            self.smallest_file_bytes = size;
            self.largest_file_bytes = size;
        } else {
            self.smallest_file_bytes = self.smallest_file_bytes.min(size);
            self.largest_file_bytes = self.largest_file_bytes.max(size);
        }
        self.entries_traversed += 1;
    }
}

#[derive(Debug, Clone)]
pub struct ItemResult {
    pub path: PathBuf,
    pub display_name: String,
    pub size: u64,
    pub is_dir: bool,
    pub errors: usize,
    pub stats: TraversalStats,
}

type SeenSet = Arc<Mutex<HashSet<(u64, u64)>>>;

pub fn configure_threads(threads: usize) {
    if threads > 0 {
        let _ = rayon::ThreadPoolBuilder::new()
            .num_threads(threads)
            .build_global();
    }
}

fn is_ignored(path: &Path, ignore_dirs: &[PathBuf]) -> bool {
    let canon = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    for ig in ignore_dirs {
        let ig_canon = fs::canonicalize(ig).unwrap_or_else(|_| ig.clone());
        if canon == ig_canon {
            return true;
        }
    }
    false
}

pub fn traverse_entry(path: &Path, options: &TraversalOptions, seen: &SeenSet) -> ItemResult {
    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => {
            let mut stats = TraversalStats::default();
            stats.num_errors = 1;
            return ItemResult {
                path: path.to_path_buf(),
                display_name: path.display().to_string(),
                size: 0,
                is_dir: path.is_dir(),
                errors: 1,
                stats,
            };
        }
    };

    let file_type = meta.file_type();
    let root_dev = meta.dev();

    if file_type.is_dir() {
        if is_ignored(path, &options.ignore_dirs) {
            let size = if options.apparent_size { meta.len() } else { meta.blocks() * 512 };
            return ItemResult {
                path: path.to_path_buf(),
                display_name: path.display().to_string(),
                size,
                is_dir: true,
                errors: 0,
                stats: TraversalStats::default(),
            };
        }

        let (size, stats) = traverse_dir_recursive(path, root_dev, options, seen);
        ItemResult {
            path: path.to_path_buf(),
            display_name: path.display().to_string(),
            size,
            is_dir: true,
            errors: stats.num_errors,
            stats,
        }
    } else if file_type.is_symlink() {
        // Symlinks are not followed during traversal
        let size = if options.apparent_size { meta.len() } else { meta.blocks() * 512 };
        ItemResult {
            path: path.to_path_buf(),
            display_name: path.display().to_string(),
            size,
            is_dir: false,
            errors: 0,
            stats: TraversalStats::default(),
        }
    } else {
        // Regular file or other
        let raw_size = if options.apparent_size { meta.len() } else { meta.blocks() * 512 };
        let mut size = raw_size;

        if !options.count_hard_links && meta.nlink() > 1 {
            let key = (meta.dev(), meta.ino());
            let mut lock = seen.lock().unwrap();
            if lock.contains(&key) {
                size = 0;
            } else {
                lock.insert(key);
            }
        }

        let mut stats = TraversalStats::default();
        stats.record_file(raw_size);

        ItemResult {
            path: path.to_path_buf(),
            display_name: path.display().to_string(),
            size,
            is_dir: false,
            errors: 0,
            stats,
        }
    }
}

fn traverse_dir_recursive(
    dir_path: &Path,
    root_dev: u64,
    options: &TraversalOptions,
    seen: &SeenSet,
) -> (u64, TraversalStats) {
    let mut total_size = match fs::symlink_metadata(dir_path) {
        Ok(m) => if options.apparent_size { m.len() } else { m.blocks() * 512 },
        Err(_) => 0,
    };

    let read_dir = match fs::read_dir(dir_path) {
        Ok(rd) => rd,
        Err(_) => {
            let mut stats = TraversalStats::default();
            stats.num_errors += 1;
            return (total_size, stats);
        }
    };

    let entries: Vec<PathBuf> = read_dir.filter_map(|e| e.ok().map(|e| e.path())).collect();

    let results: Vec<(u64, TraversalStats)> = entries
        .into_par_iter()
        .map(|entry_path| {
            let meta = match fs::symlink_metadata(&entry_path) {
                Ok(m) => m,
                Err(_) => {
                    let mut stats = TraversalStats::default();
                    stats.num_errors += 1;
                    return (0, stats);
                }
            };

            let file_type = meta.file_type();

            if file_type.is_symlink() {
                // Symlinks inside directory traversal are skipped / not counted
                return (0, TraversalStats::default());
            }

            if options.stay_on_filesystem && meta.dev() != root_dev {
                return (0, TraversalStats::default());
            }

            if file_type.is_dir() {
                if is_ignored(&entry_path, &options.ignore_dirs) {
                    let dir_size = if options.apparent_size { meta.len() } else { meta.blocks() * 512 };
                    return (dir_size, TraversalStats::default());
                }
                traverse_dir_recursive(&entry_path, root_dev, options, seen)
            } else {
                let raw_size = if options.apparent_size { meta.len() } else { meta.blocks() * 512 };
                let mut size = raw_size;

                if !options.count_hard_links && meta.nlink() > 1 {
                    let key = (meta.dev(), meta.ino());
                    let mut lock = seen.lock().unwrap();
                    if lock.contains(&key) {
                        size = 0;
                    } else {
                        lock.insert(key);
                    }
                }

                let mut stats = TraversalStats::default();
                stats.record_file(raw_size);

                (size, stats)
            }
        })
        .collect();

    let mut combined_stats = TraversalStats::default();
    for (sz, st) in results {
        total_size += sz;
        combined_stats.merge(&st);
    }

    (total_size, combined_stats)
}

pub fn traverse_inputs(inputs: &[PathBuf], options: &TraversalOptions) -> (Vec<ItemResult>, bool) {
    configure_threads(options.threads);
    let seen: SeenSet = Arc::new(Mutex::new(HashSet::new()));

    let inputs_to_use = if inputs.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        inputs.to_vec()
    };

    if inputs_to_use.len() == 1 {
        let root_path = &inputs_to_use[0];
        // Dereference if root is a symlink to directory
        let meta = fs::metadata(root_path);
        let is_dir = meta.as_ref().map(|m| m.is_dir()).unwrap_or(false);

        if is_dir {
            // Expand children of single directory input
            let read_dir = match fs::read_dir(root_path) {
                Ok(rd) => rd,
                Err(_) => {
                    let mut stats = TraversalStats::default();
                    stats.num_errors = 1;
                    return (
                        vec![ItemResult {
                            path: root_path.clone(),
                            display_name: root_path.display().to_string(),
                            size: 0,
                            is_dir: true,
                            errors: 1,
                            stats,
                        }],
                        true,
                    );
                }
            };

            let mut child_paths: Vec<PathBuf> = read_dir
                .filter_map(|e| e.ok().map(|e| e.path()))
                .collect();

            let items: Vec<ItemResult> = child_paths
                .into_par_iter()
                .map(|child| {
                    let mut res = traverse_entry(&child, options, &seen);
                    if let Some(file_name) = child.file_name() {
                        res.display_name = file_name.to_string_lossy().to_string();
                    }
                    res
                })
                .collect();

            return (items, true); // true = show total line
        } else {
            let res = traverse_entry(root_path, options, &seen);
            return (vec![res], false); // false = single file, no total line
        }
    } else {
        let items: Vec<ItemResult> = inputs_to_use
            .into_par_iter()
            .map(|input| traverse_entry(&input, options, &seen))
            .collect();

        (items, true)
    }
}
