{"command":"cat <<'EOF' > src/aggregate.rs
use crate::format::ByteFormat;
use crate::traversal::{ItemResult, TraversalStats};

pub fn run_aggregate(
    mut items: Vec<ItemResult>,
    show_total_default: bool,
    format: ByteFormat,
    stats_flag: bool,
    no_sort: bool,
    no_total: bool,
) -> i32 {
    if !no_sort {
        items.sort_by(|a, b| {
            a.size
                .cmp(&b.size)
                .then_with(|| a.display_name.cmp(&b.display_name))
        });
    }

    let mut total_size: u64 = 0;
    let mut total_errors: usize = 0;
    let mut combined_stats = TraversalStats::default();

    for item in &items {
        total_size = total_size.saturating_add(item.size);
        total_errors += item.errors;
        combined_stats.merge(&item.stats);

        let formatted_size = format.display(item.size);
        let name_str = if item.is_dir {
            format!("\x1b[36m{}\x1b[39m", item.display_name)
        } else {
            item.display_name.clone()
        };

        let err_str = match item.errors {
            0 => String::new(),
            1 => "  <1 IO Error>".to_string(),
            n => format!("  <{} IO Errors>", n),
        };

        println!("\x1b[32m{}\x1b[39m {}{}", formatted_size, name_str, err_str);
    }

    let show_total = show_total_default && !no_total;
    if show_total {
        let formatted_total = format.display(total_size);
        let err_str = match total_errors {
            0 => String::new(),
            1 => "  <1 IO Error>".to_string(),
            n => format!("  <{} IO Errors>", n),
        };
        println!("\x1b[32m{}\x1b[39m total{}", formatted_total, err_str);
    }

    if stats_flag {
        eprintln!(
            "Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}",
            combined_stats.entries_traversed,
            combined_stats.smallest_file_bytes,
            combined_stats.largest_file_bytes
        );
    }

    if total_errors > 0 {
        1
    } else {
        0
    }
}
EOF"}

