    pub sort_mode: SortMode,
    pub show_help: bool,
    pub show_delete: bool,
    pub total_size: u64,
    pub processed_entries: usize,
    pub elapsed_secs: u64,
    pub format: ByteFormat,
    pub options: TraversalOptions,
}

impl AppState {
    fn new(start_path: PathBuf, format: ByteFormat, options: TraversalOptions) -> Self {
        let mut app = Self {
            current_dir: start_path,
            entries: Vec::new(),
            list_state: ListState::default(),
            marked: HashSet::new(),
            sort_mode: SortMode::SizeDesc,
            show_help: false,
            show_delete: false,
            total_size: 0,
            processed_entries: 0,
            elapsed_secs: 0,
            format,
            options,
        };
        app.load_dir();
        app
    }

    fn load_dir(&mut self) {
        let start_time = Instant::now();
        let seen = std::sync::Arc::new(std::sync::Mutex::new(HashSet::new()));
        self.entries.clear();
        self.total_size = 0;
        self.processed_entries = 0;

        if let Ok(rd) = fs::read_dir(&self.current_dir) {
            let paths: Vec<PathBuf> = rd.filter_map(|e| e.ok().map(|e| e.path())).collect();
            self.processed_entries = paths.len();

            for path in paths {
                let item = traverse_entry(&path, &self.options, &seen);
                let name = path
                    .file_name()
                    .map(|n| n.to_string_lossy().to_string())
                    .unwrap_or_else(|| path.display().to_string());
                self.total_size += item.size;
                self.entries.push(UiEntry {
                    path,
                    name,
                    size: item.size,
                    is_dir: item.is_dir,
                });
            }
        }

        self.elapsed_secs = start_time.elapsed().as_secs();
        self.sort_entries();
        if !self.entries.is_empty() {
            self.list_state.select(Some(0));
        } else {
            self.list_state.select(None);
        }
    }

    fn sort_entries(&mut self) {
        match self.sort_mode {
            SortMode::SizeDesc => self.entries.sort_by(|a, b| b.size.cmp(&a.size).then_with(|| a.name.cmp(&b.name))),
            SortMode::SizeAsc => self.entries.sort_by(|a, b| a.size.cmp(&b.size).then_with(|| a.name.cmp(&b.name))),
            SortMode::NameAsc => self.entries.sort_by(|a, b| a.name.cmp(&b.name)),
            SortMode::NameDesc => self.entries.sort_by(|a, b| b.name.cmp(&a.name)),
        }
    }

    fn selected_entry(&self) -> Option<&UiEntry> {
        self.list_state.selected().and_then(|i| self.entries.get(i))
    }

    fn move_down(&mut self, amount: usize) {
        if self.entries.is_empty() {
            return;
        }
        let current = self.list_state.selected().unwrap_or(0);
        let next = (current + amount).min(self.entries.len() - 1);
        self.list_state.select(Some(next));
    }

    fn move_up(&mut self, amount: usize) {
        if self.entries.is_empty() {
            return;
        }
        let current = self.list_state.selected().unwrap_or(0);
        let next = current.saturating_sub(amount);
        self.list_state.select(Some(next));
    }

    fn toggle_mark_current(&mut self) {
        if let Some(entry) = self.selected_entry() {
            let path = entry.path.clone();
            if self.marked.contains(&path) {
                self.marked.remove(&path);
            } else {
                self.marked.insert(path);
            }
        }
    }

    fn toggle_mark_all(&mut self) {
        if self.marked.len() == self.entries.len() {
            self.marked.clear();
        } else {
            for entry in &self.entries {
                self.marked.insert(entry.path.clone());
            }
        }
    }

    fn delete_marked(&mut self) {
        let to_remove: Vec<PathBuf> = if !self.marked.is_empty() {
            self.marked.iter().cloned().collect()
        } else if let Some(entry) = self.selected_entry() {
            vec![entry.path.clone()]
        } else {
            vec![]
        };

        for path in to_remove {
            if path.is_dir() {
                let _ = fs::remove_dir_all(&path);
            } else {
                let _ = fs::remove_file(&path);
            }
            self.marked.remove(&path);
        }

        self.show_delete = false;
        self.load_dir();
    }
}

pub fn run_interactive(start_paths: Vec<PathBuf>, format: ByteFormat, options: TraversalOptions) -> Result<(), io::Error> {
    let start_path = if start_paths.is_empty() {
        PathBuf::from(".")
    } else {
        start_paths[0].clone()
    };

    let abs_start = fs::canonicalize(&start_path).unwrap_or(start_path);

    enable_raw_mode()?;
    stdout().execute(EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout());
    let mut terminal = Terminal::new(backend)?;

    let mut app = AppState::new(abs_start, format, options);

    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if app.show_help {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc | KeyCode::Char('?') => app.show_help = false,
                        _ => {}
                    }
                    continue;
                }

                if app.show_delete {
                    match key.code {
                        KeyCode::Char('d') | KeyCode::Enter => app.delete_marked(),
                        KeyCode::Char('q') | KeyCode::Esc => app.show_delete = false,
                        _ => {}
                    }
                    continue;
                }

                match key.code {
                    KeyCode::Char('q') => {
                        if let Some(parent) = app.current_dir.parent().map(|p| p.to_path_buf()) {
                            if parent != app.current_dir {
                                app.current_dir = parent;
                                app.load_dir();
                                continue;
                            }
                        }
                        break;
                    }
                    KeyCode::Esc => break,
                    KeyCode::Char('?') => app.show_help = true,
                    KeyCode::Char('j') | KeyCode::Down => app.move_down(1),
                    KeyCode::Char('k') | KeyCode::Up => app.move_up(1),
                    KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => app.move_down(10),
                    KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => app.move_up(10),
                    KeyCode::Char('g') | KeyCode::Home => app.move_up(app.entries.len()),
                    KeyCode::Char('G') | KeyCode::End => app.move_down(app.entries.len()),
                    KeyCode::Char('o') | KeyCode::Char('l') | KeyCode::Enter | KeyCode::Right => {
                        if let Some(entry) = app.selected_entry() {
                            if entry.is_dir {
                                app.current_dir = entry.path.clone();
                                app.load_dir();
                            }
                        }
                    }
                    KeyCode::Char('u') | KeyCode::Char('h') | KeyCode::Left | KeyCode::Backspace => {
                        if let Some(parent) = app.current_dir.parent().map(|p| p.to_path_buf()) {
                            app.current_dir = parent;
                            app.load_dir();
                        }
                    }
                    KeyCode::Char('s') => {
                        app.sort_mode = app.sort_mode.next();
                        app.sort_entries();
                    }
                    KeyCode::Char(' ') => app.toggle_mark_current(),
                    KeyCode::Char('a') => app.toggle_mark_all(),
                    KeyCode::Char('d') => {
                        if !app.marked.is_empty() || app.selected_entry().is_some() {
                            app.show_delete = true;
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    stdout().execute(LeaveAlternateScreen)?;
    Ok(())
}

fn ui(f: &mut ratatui::Frame, app: &mut AppState) {
    let size = f.area();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1), // Top header
            Constraint::Min(5),    // Main content
            Constraint::Length(1), // Footer mark key shortcuts
            Constraint::Length(1), // Status bar
        ])
        .split(size);

    // Top header bar
    let header_text = format!(" Disk Usage Analyzer v2.32.2    (press ? for help)");
    let header = Paragraph::new(header_text).style(
        Style::default()
            .bg(Color::White)
            .fg(Color::Black)
            .add_modifier(Modifier::BOLD),
    );
    f.render_widget(header, chunks[0]);

    // Main pane
    let visible_count = app.entries.len();
    let total_fmt = app.format.display(app.total_size);

    let title_str = format!(
        " /{} ({} visible, {} total, {}) ",
        app.current_dir.display(),
        visible_count,
        visible_count,
        total_fmt.trim()
    );

    let block = Block::default()
        .title(title_str)
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));

    let inner_area = block.inner(chunks[1]);
    f.render_widget(block, chunks[1]);

    let list_items: Vec<ListItem> = app
        .entries
        .iter()
        .map(|entry| {
            let is_marked = app.marked.contains(&entry.path);
            let size_str = app.format.display(entry.size);

            let pct = if app.total_size > 0 {
                (entry.size as f64 / app.total_size as f64 * 100.0) as u32
            } else {
                0
            };

            let bar_len = (pct / 10).min(10) as usize;
            let bar_str = format!("{:<10}", "█".repeat(bar_len));

            let name_style = if entry.is_dir {
                Style::default().fg(Color::Cyan)
            } else {
                Style::default().fg(Color::White)
            };

            let mark_symbol = if is_marked { " *" } else { "  " };

            let spans = vec![
                Span::styled(size_str, Style::default().fg(Color::Green)),
                Span::raw(" | "),
                Span::styled(format!("{:>5.1}%", pct), Style::default().fg(Color::Yellow)),
                Span::raw("  "),
                Span::styled(bar_str, Style::default().fg(Color::Green)),
                Span::raw(" |"),
                Span::raw(mark_symbol),
                Span::styled(entry.name.clone(), name_style),
            ];

            ListItem::new(Line::from(spans))
        })
        .collect();

    let list = List::new(list_items).highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    );

    f.render_stateful_widget(list, inner_area, &mut app.list_state);

    // Footer mark key shortcuts
    let footer_hints = " mark-move = d | mark-toggle = space | toggle-all = a ";
    let footer_p = Paragraph::new(footer_hints).style(Style::default().fg(Color::DarkGray));
    f.render_widget(footer_p, chunks[2]);

    // Status bar
    let status_str = format!(
        "Sort mode: {}  Total disk usage: {}  Processed {} entries in {}s",
        app.sort_mode.name(),
        total_fmt.trim(),
        app.processed_entries,
        app.elapsed_secs
    );

    let status_p = Paragraph::new(status_str).style(
        Style::default()
            .bg(Color::White)
            .fg(Color::Black)
            .add_modifier(Modifier::REVERSED),
    );
    f.render_widget(status_p, chunks[3]);

    // Render Help Overlay if active
    if app.show_help {
        render_help_overlay(f, size);
    }

    // Render Delete Overlay if active
    if app.show_delete {
        render_delete_overlay(f, size, app);
    }
}

fn render_help_overlay(f: &mut ratatui::Frame, area: Rect) {
    let popup_area = Rect {
        x: area.width / 4,
        y: area.height / 6,
        width: area.width / 2,
        height: (area.height * 2) / 3,
    };

    f.render_widget(Clear, popup_area);

    let help_text = vec![
        Line::from(Span::styled("Pane control", Style::default().add_modifier(Modifier::UNDERLINE))),
        Line::from("  q/<Esc>    => Close current pane"),
        Line::from("  <Tab>      => Cycle open panes"),
        Line::from("  ?          => Toggle help"),
        Line::from(""),
        Line::from(Span::styled("Navigation", Style::default().add_modifier(Modifier::UNDERLINE))),
        Line::from("  j/<Down>   => Move down 1 entry"),
        Line::from("  k/<Up>     => Move up 1 entry"),
        Line::from("  o/l/Enter  => Descend into directory"),
        Line::from("  u/h/Left   => Ascent parent level"),
        Line::from("  Ctrl+d     => Move down 10 entries"),
        Line::from("  Ctrl+u     => Move up 10 entries"),
        Line::from("  g/Home     => Move to top"),
        Line::from("  G/End      => Move to bottom"),
        Line::from(""),
        Line::from(Span::styled("Marking & Deletion", Style::default().add_modifier(Modifier::UNDERLINE))),
        Line::from("  space      => Toggle mark"),
        Line::from("  a          => Toggle mark all"),
        Line::from("  d          => Delete marked/current"),
        Line::from("  s          => Cycle sort mode"),
    ];

    let block = Block::default()
        .title(" Help ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Yellow));

    let help_p = Paragraph::new(help_text).block(block);
    f.render_widget(help_p, popup_area);
}

fn render_delete_overlay(f: &mut ratatui::Frame, area: Rect, app: &AppState) {
    let popup_area = Rect {
        x: area.width / 4,
        y: area.height / 3,
        width: area.width / 2,
        height: area.height / 3,
    };

    f.render_widget(Clear, popup_area);

    let count = if !app.marked.is_empty() {
        app.marked.len()
    } else {
        1
    };

    let text = vec![
        Line::from(format!("Are you sure you want to delete {} item(s)?", count)),
        Line::from(""),
        Line::from(Span::styled("Press 'd' or 'Enter' to CONFIRM, 'q' or 'Esc' to CANCEL", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))),
    ];

    let block = Block::default()
        .title(" Confirm Deletion ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Red));

    let p = Paragraph::new(text).block(block);
    f.render_widget(p, popup_area);
}
EOF"}

