        y: area.height / 3,
        width: area.width / 2,
        height: area.height / 3,
    };

    f.render_widget(Clear, popup_area);

    let count = if !app.marked.is_empty() {
        app.marked.len()
    } else {
        1
    };

    let text = vec![
        Line::from(format!("Are you sure you want to delete {} item(s)?", count)),
        Line::from(""),
        Line::from(Span::styled("Press 'd' or 'Enter' to CONFIRM, 'q' or 'Esc' to CANCEL", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))),
    ];

    let block = Block::default()
        .title(" Confirm Deletion ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Red));

    let p = Paragraph::new(text).block(block);
    f.render_widget(p, popup_area);
}
EOF"}

