use std::process::exit;
use args::{parse_cli, SubCommand};
use traversal::TraversalOptions;

fn main() {
    let cli = parse_cli();

    if let Some(ref log_path) = cli.log_file {
        logging::init_log(log_path);
        logging::log_info(&format!("dua options={:?}", cli));
        let ignore_list: Vec<String> = cli.ignore_dirs.iter().map(|p| p.display().to_string()).collect();
        logging::log_info(&format!("Ignoring canonicalized {{{}}}", ignore_list.join(", ")));
    }

    let options = TraversalOptions {
        threads: cli.threads,
        apparent_size: cli.apparent_size,
        count_hard_links: cli.count_hard_links,
        stay_on_filesystem: cli.stay_on_filesystem,
        ignore_dirs: cli.ignore_dirs,
    };

    match cli.subcommand {
        SubCommand::Completions { shell } => {
            completions::run(&shell);
        }
        SubCommand::Interactive { inputs, .. } => {
            if let Err(e) = interactive::run_interactive(inputs, cli.format, options) {
                eprintln!("Error in interactive mode: {}", e);
                exit(1);
            }
        }
        SubCommand::Aggregate {
            stats,
            no_sort,
            no_total,
            inputs,
        } => {
            let (items, show_total) = traversal::traverse_inputs(&inputs, &options);
            let code = aggregate::run_aggregate(
                items,
                show_total,
                cli.format,
                stats,
                no_sort,
                no_total,
            );
            exit(code);
        }
    }
}
